func contains(values []string, needle string) bool {
	for _, v := range values {
		if v == needle {
			return true
		}
	}
	return false
}

func containsSubsequence(values, needle []string) bool {
	if len(needle) == 0 {
		return true
	}
	for start := 0; start+len(needle) <= len(values); start++ {
		ok := true
		for i, w := range needle {
			if values[start+i] != w {
				ok = false
				break
			}
		}
		if ok {
			return true
		}
	}
	return false
}

package cli

import (
	"context"
	"fmt"
	"io"
	"net/url"
	"os"
	"strings"

	"github.com/spf13/cobra"

	agyadapter "github.com/aoagents/agent-orchestrator/backend/internal/adapters/agent/agy"
	"github.com/aoagents/agent-orchestrator/backend/internal/adapters/agent/claudecode"
	"github.com/aoagents/agent-orchestrator/backend/internal/adapters/agent/cline"
	codexadapter "github.com/aoagents/agent-orchestrator/backend/internal/adapters/agent/codex"
	"github.com/aoagents/agent-orchestrator/backend/internal/adapters/agent/copilot"
	"github.com/aoagents/agent-orchestrator/backend/internal/adapters/agent/cursor"
	"github.com/aoagents/agent-orchestrator/backend/internal/adapters/agent/droid"
	gooseadapter "github.com/aoagents/agent-orchestrator/backend/internal/adapters/agent/goose"
	"github.com/aoagents/agent-orchestrator/backend/internal/adapters/agent/qwen"
)

// setActivityAPIRequest mirrors the daemon's SetActivityRequest body for
// POST /api/v1/sessions/{id}/activity. The CLI keeps its own copy so it need
// not import httpd.
type setActivityAPIRequest struct {
	State string `json:"state"`
}

// newHooksCommand builds the hidden `ao hooks <agent> <event>` command that
// agent CLIs invoke from their workspace-local hook config. It reads the native
// hook payload from stdin and the AO session id from AO_SESSION_ID, derives an
// activity state for the event, and reports it to the daemon.
//
// It is best-effort by design: a hook must never break the user's agent, so a
// non-AO session (no AO_SESSION_ID), an event that carries no activity signal,
// or an unreachable daemon all exit 0 rather than erroring.
func newHooksCommand(ctx *commandContext) *cobra.Command {
	return &cobra.Command{
		Use:    "hooks <agent> <event>",
		Short:  "Receive an agent hook callback (internal)",
		Hidden: true,
		Args:   cobra.ExactArgs(2),
		RunE: func(cmd *cobra.Command, args []string) error {
			return ctx.runHook(cmd.Context(), args[0], args[1])
		},
	}
}

func (c *commandContext) runHook(ctx context.Context, agent, event string) error {
	sessionID := strings.TrimSpace(os.Getenv("AO_SESSION_ID"))
	if sessionID == "" {
		// Not an AO-managed session. Return before reading stdin so a manual
		// invocation without a piped payload can't block on EOF.
		return nil
	}
	payload, _ := io.ReadAll(c.deps.In) // read error -> empty payload, handled by the deriver.

	var state string
	switch agent {
	case "claude-code", "grok", "continue", "devin":
		// grok, continue, and devin use the Claude Code compatibility layer for hooks
		// (see https://docs.x.ai/build/features/skills-plugins-marketplaces
		// "Grok automatically reads Claude Code ... hooks ...").
		// Payload shapes match, so we can share the derive logic.
		s, ok := claudecode.DeriveActivityState(event, payload)
		if !ok {
			return nil // event carries no activity signal.
		}
		state = string(s)
	case "codex":
		s, ok := codexadapter.DeriveActivityState(event, payload)
		if !ok {
			return nil // event carries no activity signal.
		}
		state = string(s)
	case "droid":
		// Droid has no Claude Code compatibility layer and its Notification
		// payload omits notification_type, so it ships its own deriver.
		s, ok := droid.DeriveActivityState(event, payload)
		if !ok {
			return nil // event carries no activity signal.
		}
		state = string(s)
	case "agy":
		s, ok := agyadapter.DeriveActivityState(event, payload)
		if !ok {
			return nil // event carries no activity signal.
		}
		state = string(s)
	case "cursor":
		s, ok := cursor.DeriveActivityState(event, payload)
		if !ok {
			return nil // event carries no activity signal.
		}
		state = string(s)
	case "qwen":
		s, ok := qwen.DeriveActivityState(event, payload)
		if !ok {
			return nil // event carries no activity signal.
		}
		state = string(s)
	case "copilot":
		s, ok := copilot.DeriveActivityState(event, payload)
		if !ok {
			return nil // event carries no activity signal.
		}
		state = string(s)
	case "goose":
		s, ok := gooseadapter.DeriveActivityState(event, payload)
		if !ok {
			return nil // event carries no activity signal.
		}
		state = string(s)
	case "cline":
		s, ok := cline.DeriveActivityState(event, payload)
		if !ok {
			return nil // event carries no activity signal.
		}
		state = string(s)
	default:
		return nil // unknown agent: nothing to report.
	}

	path := "sessions/" + url.PathEscape(sessionID) + "/activity"
	if err := c.postJSON(ctx, path, setActivityAPIRequest{State: state}, nil); err != nil {
		// Report to stderr (the agent's hook runner captures it) for diagnosis,
		// but exit 0: a failed activity report must not disrupt the agent.
		fmt.Fprintf(c.deps.Err, "ao hooks %s %s: %v\n", agent, event, err)
	}
	return nil
}

package domain

import "time"

// ActivityState is how busy the agent is, reported via the agent's CLI hook
// callbacks (see docs/agent/README.md), not inferred from transcript/JSONL
type ActivityState string

// Activity states. WaitingInput is sticky (see IsSticky).
const (
	ActivityActive       ActivityState = "active"
	ActivityIdle         ActivityState = "idle"
	ActivityWaitingInput ActivityState = "waiting_input"
	ActivityExited       ActivityState = "exited"
)

// IsSticky reports whether an activity state must NOT be aged/demoted by the
// passage of time (a paused agent is still paused until a new signal says so).
func (a ActivityState) IsSticky() bool {
	return a == ActivityWaitingInput
}

// Activity captures the persisted activity reading: the state and when it was
// last observed.
type Activity struct {
	State          ActivityState `json:"state"`
	LastActivityAt time.Time     `json:"lastActivityAt"`
}

