1	package zellij
2	
3	import (
4		"fmt"
5		"sort"
6		"strconv"
7		"strings"
8	
9		"github.com/aoagents/agent-orchestrator/backend/internal/ports"
10	)
11	
12	const (
13		agentPaneName     = "agent"
14		defaultChunkBytes = 16 * 1024
15	)
16	
17	func versionArgs() []string {
18		return []string{"--version"}
19	}
20	
21	func createSessionArgs(id, layoutPath string) []string {
22		return []string{
23			"attach", "--create-background", id,
24			"options",
25			"--default-layout", layoutPath,
26			"--pane-frames", "false",
27			"--session-serialization", "false",
28			"--show-startup-tips", "false",
29			"--show-release-notes", "false",
30		}
31	}
32	
33	func listPanesArgs(id string) []string {
34		return []string{"--session", id, "action", "list-panes", "--all", "--json"}
35	}
36	
37	func pasteArgs(id, paneID, chunk string) []string {
38		return []string{"--session", id, "action", "paste", "--pane-id", paneID, chunk}
39	}
40	
41	func sendEnterArgs(id, paneID string) []string {
42		return []string{"--session", id, "action", "send-keys", "--pane-id", paneID, "Enter"}
43	}
44	
45	func dumpScreenArgs(id, paneID string) []string {
46		return []string{"--session", id, "action", "dump-screen", "--pane-id", paneID, "--full"}
47	}
48	
49	func listSessionsArgs() []string {
50		return []string{"list-sessions", "--no-formatting"}
51	}
52	
53	func killSessionArgs(id string) []string {
54		return []string{"kill-session", id}
55	}
56	
57	func attachArgs(id string) []string {
58		return []string{"attach", id}
59	}
60	
61	func handleIDValue(sessionID, paneID string) string {
62		return sessionID + "/" + paneID
63	}
64	
65	func terminalPaneID(id int) string {
66		return fmt.Sprintf("terminal_%d", id)
67	}
68	
69	func buildLayout(cfg ports.RuntimeConfig, shellPath string) string {
70		spec := shellLaunchSpecFor(shellPath)
71		shellCommand := shellLaunchCommand(cfg, shellPath, spec)
72		return layoutString(cfg.WorkspacePath, shellPath, spec.args, shellCommand)
73	}
74	
75	type shellLaunchSpec struct {
76		args []string
77	}
78	
79	func shellLaunchSpecFor(shellPath string) shellLaunchSpec {
80		base := strings.ToLower(filepathBase(shellPath))
81		if strings.Contains(base, "cmd") {
82			return shellLaunchSpec{args: []string{"/D", "/S", "/K"}}
83		}
84		if strings.Contains(base, "powershell") || strings.Contains(base, "pwsh") {
85			return shellLaunchSpec{args: []string{"-NoLogo", "-NoProfile", "-NoExit", "-Command"}}
86		}
87		return shellLaunchSpec{args: []string{"-lc"}}
88	}
89	
90	func layoutString(workspacePath, shellPath string, shellArgs []string, shellCommand string) string {
91		return "layout {\n" +
92			"  cwd " + kdlQuote(workspacePath) + "\n" +
93			"  pane command=" + kdlQuote(shellPath) + " name=" + kdlQuote(agentPaneName) + " {\n" +
94			"    args " + kdlJoin(shellArgs) + " " + kdlQuote(shellCommand) + "\n" +
95			"  }\n" +
96			"}\n"
97	}
98	
99	func shellLaunchCommand(cfg ports.RuntimeConfig, shellPath string, spec shellLaunchSpec) string {
100		if len(spec.args) > 0 && spec.args[0] == "-NoLogo" {
101			return wrapLaunchCommandPowerShell(cfg)
102		}
103		if len(spec.args) > 0 && spec.args[0] == "/D" {
104			return wrapLaunchCommandCmd(cfg)
105		}
106		return wrapLaunchCommandUnix(cfg, shellPath)
107	}
108	
109	func wrapLaunchCommandUnix(cfg ports.RuntimeConfig, shellPath string) string {
110		path := cfg.Env["PATH"]
111		if path == "" {
112			path = getenv("PATH")
