// Package conformance is the eval-matrix-as-code for AO's agent adapters. It
// runs every registered adapter through the ports.Agent contract along the six
// dimensions the team verifies by hand — spawn, activity, session info,
// permissions, hook install, and exact commands — and returns a structured
// Result per (adapter, dimension) cell.
//
// Every check is in-process and hermetic: it builds commands, installs hooks
// into a temp worktree, and reads back the result, needing zero agent binaries
// and touching no global state (it never calls an adapter's PreLaunch, which may
// write to the user's real config). That makes it safe to run in CI as a
// regression guard and fast enough for the `ao evalrig` proving ground to render
// the live matrix from the same Results.
package conformance

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strings"

	"github.com/aoagents/agent-orchestrator/backend/internal/adapters/agent/activitydispatch"
	"github.com/aoagents/agent-orchestrator/backend/internal/adapters/agent/registry"
	"github.com/aoagents/agent-orchestrator/backend/internal/ports"
)

// Status is a conformance cell verdict.
type Status string

// The verdicts a conformance check can return.
const (
	// StatusPass: the adapter satisfies the dimension's contract.
	StatusPass Status = "pass"
	// StatusFail: the adapter violates a hard contract invariant.
	StatusFail Status = "fail"
	// StatusGap: the adapter is wired but its integration is broken end-to-end
	// (e.g. installs `ao hooks <tok>` callbacks that nothing dispatches).
	StatusGap Status = "gap"
	// StatusSkip: the dimension does not apply to this adapter (a known,
	// deliberate limitation — e.g. an adapter with no hook support at all).
	StatusSkip Status = "skip"
)

// Dimension names, stable for filtering subtests and rendering the matrix.
const (
	DimSpawn       = "spawn"
	DimActivity    = "activity"
	DimSessionInfo = "sessioninfo"
	DimPermissions = "permissions"
	DimHooks       = "hooks"
	DimCommands    = "commands"
)

// Dimensions is the column order of the eval matrix.
var Dimensions = []string{DimSpawn, DimActivity, DimSessionInfo, DimPermissions, DimHooks, DimCommands}

// Result is one cell of the eval matrix: a verdict for a (harness, dimension)
// pair, with a human-facing detail and evidence lines suitable for display.
type Result struct {
	Harness   string
	Dimension string
	Status    Status
	Detail    string
	Evidence  []string
}

// evalPrompt carries a distinctive marker so the spawn check can detect whether
// an adapter embeds the prompt in argv (in_command) or withholds it
// (after_start) without false matches against flags.
const evalPrompt = "Add a health check endpoint (AOEVAL)"

// evalSessionID is a fixed AO session id so adapters that derive a native
// session id from it (e.g. Claude's --session-id UUID) produce stable golden
// commands.
const evalSessionID = "aoeval000001"

// evalAgentSessionID is the native session id seeded into metadata for the
// SessionInfo and restore checks.
const evalAgentSessionID = "aoeval-native-1"

// aoHooksTokenRe matches the agent token an installed hook callback invokes:
// `ao hooks <token> <event>`. The Activity check scans the files an adapter
// writes for these to learn which dispatcher each callback expects.
var aoHooksTokenRe = regexp.MustCompile(`ao hooks ([A-Za-z0-9_-]+)`)

// RunAll runs every registered agent adapter through every dimension and
// returns the flattened matrix, ordered by harness then dimension.
func RunAll(ctx context.Context) []Result {
	var out []Result
	for _, ha := range registry.Harnessed() {
		out = append(out, Run(ctx, ha)...)
	}
	return out
}

// Run runs one adapter through all six dimensions.
func Run(ctx context.Context, ha registry.HarnessAgent) []Result {
	return []Result{
		checkSpawn(ctx, ha),
		checkActivity(ctx, ha),
		checkSessionInfo(ctx, ha),
		checkPermissions(ctx, ha),
		checkHooks(ctx, ha),
		checkCommands(ctx, ha),
	}
}

// checkSpawn verifies the launch command is well-formed, deterministic, and
// consistent with the adapter's declared prompt-delivery strategy.
func checkSpawn(ctx context.Context, ha registry.HarnessAgent) Result {
	r := Result{Harness: string(ha.Harness), Dimension: DimSpawn}
	ws, cleanup, err := tempWorkspace()
	if err != nil {
		return fail(r, "temp workspace: %v", err)
	}
	defer cleanup()

	cfg := launchConfig(ctx, ha.Agent, ws)
	cmd, err := ha.Agent.GetLaunchCommand(ctx, cfg)
	if err != nil {
		return fail(r, "GetLaunchCommand: %v", err)
	}
	if len(cmd) == 0 {
		return fail(r, "GetLaunchCommand returned empty argv")
	}
	for i, tok := range cmd {
		if tok == "" {
			return fail(r, "argv[%d] is an empty string: %v", i, cmd)
		}
	}

	cmd2, err := ha.Agent.GetLaunchCommand(ctx, cfg)
	if err != nil {
		return fail(r, "GetLaunchCommand (2nd call): %v", err)
	}
	if strings.Join(cmd, "\x00") != strings.Join(cmd2, "\x00") {
		return fail(r, "GetLaunchCommand not deterministic:\n  %v\n  %v", cmd, cmd2)
	}

	strategy, err := ha.Agent.GetPromptDeliveryStrategy(ctx, cfg)
	if err != nil {
		return fail(r, "GetPromptDeliveryStrategy: %v", err)
	}
	joined := strings.Join(cmd, " ")
	embedded := strings.Contains(joined, evalPrompt)
	switch strategy {
	case ports.PromptDeliveryInCommand:
		if !embedded {
			return fail(r, "strategy=in_command but prompt is absent from argv: %v", normalizeArgv(cmd))
		}
	case ports.PromptDeliveryAfterStart:
		if embedded {
			return fail(r, "strategy=after_start but prompt is embedded in argv: %v", normalizeArgv(cmd))
		}
	default:
		return fail(r, "GetPromptDeliveryStrategy returned invalid value %q", strategy)
	}

	r.Status = StatusPass
	r.Detail = fmt.Sprintf("deterministic argv, prompt delivery %q honored", strategy)
	r.Evidence = []string{strings.Join(normalizeArgv(cmd), " ")}
	return r
}

// checkActivity installs the adapter's hooks and learns which `ao hooks <tok>`
// dispatchers its callbacks expect, then pins that every expected token has a
// deriver registered in activitydispatch. An adapter that installs no callbacks
// is a deliberate limitation (Skip), not a failure.
func checkActivity(ctx context.Context, ha registry.HarnessAgent) Result {
	r := Result{Harness: string(ha.Harness), Dimension: DimActivity}
	ws, cleanup, err := tempWorkspace()
	if err != nil {
		return fail(r, "temp workspace: %v", err)
	}
	defer cleanup()

	if err := ha.Agent.GetAgentHooks(ctx, hookConfig(ws)); err != nil {
		return fail(r, "GetAgentHooks: %v", err)
	}
	tokens, err := scanInstalledTokens(ws)
	if err != nil {
		return fail(r, "scan installed hook callbacks: %v", err)
	}
	if len(tokens) == 0 {
		r.Status = StatusSkip
		r.Detail = "installs no `ao hooks` callbacks — no activity reporting (adapter limitation)"
		return r
	}

	var missing, dispatched []string
	for _, tok := range sortedKeys(tokens) {
		if _, ok := activitydispatch.Derivers[tok]; ok {
			dispatched = append(dispatched, tok)
		} else {
			missing = append(missing, tok)
		}
	}
	r.Evidence = []string{"callbacks: ao hooks " + strings.Join(append(append([]string{}, dispatched...), missing...), ", ")}
	if len(missing) > 0 {
		r.Status = StatusGap
		r.Detail = fmt.Sprintf("installs `ao hooks %s` callbacks but no deriver is registered in activitydispatch.Derivers — activity is silently never reported", strings.Join(missing, ", "))
		return r
	}
	r.Status = StatusPass
	r.Detail = fmt.Sprintf("callbacks route to registered derivers: %s", strings.Join(dispatched, ", "))
	return r
}

// checkSessionInfo verifies SessionInfo is derived from metadata only — it must
// return false on empty metadata and populate from the agentSessionId key even
// when the workspace path does not exist (proving it never reads transcripts).
func checkSessionInfo(ctx context.Context, ha registry.HarnessAgent) Result {
	r := Result{Harness: string(ha.Harness), Dimension: DimSessionInfo}
	const missingPath = "/nonexistent/aoeval-no-such-worktree"

	empty, ok, err := ha.Agent.SessionInfo(ctx, ports.SessionRef{ID: evalSessionID, WorkspacePath: missingPath})
	if err != nil {
		return fail(r, "SessionInfo(empty metadata) errored: %v", err)
	}
	if ok {
		return fail(r, "SessionInfo(empty metadata) returned ok=true: %+v", empty)
	}

	info, ok, err := ha.Agent.SessionInfo(ctx, ports.SessionRef{
		ID:            evalSessionID,
		WorkspacePath: missingPath, // does not exist: proves no transcript/cache read.
		Metadata:      map[string]string{ports.MetadataKeyAgentSessionID: evalAgentSessionID},
	})
	if err != nil {
		return fail(r, "SessionInfo(metadata, nonexistent workspace) errored — likely reads the filesystem: %v", err)
	}
	if !ok {
		return fail(r, "SessionInfo did not surface metadata key %q", ports.MetadataKeyAgentSessionID)
	}
	if info.AgentSessionID != evalAgentSessionID {
		return fail(r, "AgentSessionID = %q, want %q", info.AgentSessionID, evalAgentSessionID)
	}

	r.Status = StatusPass
	r.Detail = "derived from metadata; no filesystem read"
	if info.Title != "" || info.Summary != "" {
		r.Evidence = append(r.Evidence, fmt.Sprintf("title=%q summary=%q", info.Title, info.Summary))
	}
	return r
}

// checkPermissions verifies the default mode emits no flag the explicit modes
// lack, and that the adapter distinguishes at least one non-default mode. An
// adapter that maps no permission modes is a limitation (Skip).
func checkPermissions(ctx context.Context, ha registry.HarnessAgent) Result {
	r := Result{Harness: string(ha.Harness), Dimension: DimPermissions}
	ws, cleanup, err := tempWorkspace()
	if err != nil {
		return fail(r, "temp workspace: %v", err)
	}
	defer cleanup()

	modes := []ports.PermissionMode{
		ports.PermissionModeDefault,
		ports.PermissionModeAcceptEdits,
		ports.PermissionModeAuto,
		ports.PermissionModeBypassPermissions,
	}
	argvByMode := map[ports.PermissionMode][]string{}
	for _, m := range modes {
		cfg := launchConfig(ctx, ha.Agent, ws)
		cfg.Permissions = m
		cmd, err := ha.Agent.GetLaunchCommand(ctx, cfg)
		if err != nil {
			return fail(r, "GetLaunchCommand(%s): %v", m, err)
		}
		argvByMode[m] = cmd
	}

	def := argvByMode[ports.PermissionModeDefault]
	distinct := false
	for _, m := range modes[1:] {
		mode := argvByMode[m]
		if !isMultisetSubset(def, mode) {
			added := tokensRemoved(mode, def)
			return fail(r, "default mode emits token(s) %v that mode %s lacks — default must add no permission flag", added, m)
		}
		if strings.Join(def, "\x00") != strings.Join(mode, "\x00") {
			distinct = true
		}
		if added := tokensAdded(def, mode); len(added) > 0 {
			r.Evidence = append(r.Evidence, fmt.Sprintf("%s adds: %s", m, strings.Join(added, " ")))
		}
	}
	if !distinct {
		r.Status = StatusSkip
		r.Detail = "all permission modes produce identical argv — adapter maps no permission flags"
		return r
	}
	r.Status = StatusPass
	r.Detail = "default emits no flag; non-default modes map to distinct flags"
	return r
}

// checkHooks verifies hook installation is idempotent (a second install changes
// nothing) and, when the adapter exposes them, that AreHooksInstalled /
// UninstallHooks round-trip. The files written are reported as evidence so the
// reviewer can confirm AO targets a worktree-local, non-tracked config file
// (e.g. settings.local.json) rather than a git-tracked one.
func checkHooks(ctx context.Context, ha registry.HarnessAgent) Result {
	r := Result{Harness: string(ha.Harness), Dimension: DimHooks}
	ws, cleanup, err := tempWorkspace()
	if err != nil {
		return fail(r, "temp workspace: %v", err)
	}
	defer cleanup()

	cfg := hookConfig(ws)
	if err := ha.Agent.GetAgentHooks(ctx, cfg); err != nil {
		return fail(r, "GetAgentHooks (1st install): %v", err)
	}
	first, err := snapshotTree(ws)
	if err != nil {
		return fail(r, "snapshot after install: %v", err)
	}
	if err := ha.Agent.GetAgentHooks(ctx, cfg); err != nil {
		return fail(r, "GetAgentHooks (2nd install): %v", err)
	}
	second, err := snapshotTree(ws)
	if err != nil {
		return fail(r, "snapshot after 2nd install: %v", err)
	}
	if !sameSnapshot(first, second) {
		return fail(r, "install is not idempotent: a 2nd GetAgentHooks changed the worktree (duplicate hooks?)")
	}

	if len(first) == 0 {
		r.Status = StatusSkip
		r.Detail = "GetAgentHooks installs nothing (adapter limitation)"
		return r
	}
	r.Evidence = append(r.Evidence, "writes: "+strings.Join(sortedKeys(toSet(first)), ", "))

	// Optional uninstall lifecycle, when the adapter implements it.
	type uninstaller interface {
		UninstallHooks(context.Context, string) error
		AreHooksInstalled(context.Context, string) (bool, error)
	}
	if u, ok := ha.Agent.(uninstaller); ok {
		installed, err := u.AreHooksInstalled(ctx, ws)
		if err != nil {
			return fail(r, "AreHooksInstalled after install: %v", err)
		}
		if !installed {
			return fail(r, "AreHooksInstalled = false right after install")
		}
		if err := u.UninstallHooks(ctx, ws); err != nil {
			return fail(r, "UninstallHooks: %v", err)
		}
		installed, err = u.AreHooksInstalled(ctx, ws)
		if err != nil {
			return fail(r, "AreHooksInstalled after uninstall: %v", err)
		}
		if installed {
			return fail(r, "AreHooksInstalled = true after uninstall")
		}
		if err := u.UninstallHooks(ctx, ws); err != nil {
			return fail(r, "UninstallHooks (2nd, should be no-op): %v", err)
		}
		r.Detail = "idempotent install; uninstall round-trips"
	} else {
		r.Detail = "idempotent install (no uninstall lifecycle exposed)"
	}
	r.Status = StatusPass
	return r
}

// checkCommands captures the normalized launch and restore argv for review
// against the agent's real CLI docs (dimension #6). It is informational — drift
// is enforced by the golden snapshot in conformance_test.go — so it only fails
// when command construction itself errors.
func checkCommands(ctx context.Context, ha registry.HarnessAgent) Result {
	r := Result{Harness: string(ha.Harness), Dimension: DimCommands}
	ws, cleanup, err := tempWorkspace()
	if err != nil {
		return fail(r, "temp workspace: %v", err)
	}
	defer cleanup()

	cmd, err := ha.Agent.GetLaunchCommand(ctx, launchConfig(ctx, ha.Agent, ws))
	if err != nil {
		return fail(r, "GetLaunchCommand: %v", err)
	}
	r.Evidence = append(r.Evidence, "launch:  "+strings.Join(normalizeArgv(cmd), " "))

	restore, ok, err := ha.Agent.GetRestoreCommand(ctx, restoreConfig(ws))
	if err != nil {
		return fail(r, "GetRestoreCommand: %v", err)
	}
	if ok {
		r.Evidence = append(r.Evidence, "restore: "+strings.Join(normalizeArgv(restore), " "))
	} else {
		r.Evidence = append(r.Evidence, "restore: (not supported)")
	}

	r.Status = StatusPass
	r.Detail = "commands constructed; review against the agent's CLI docs"
	return r
}

// CommandEvidence returns the normalized launch and restore argv lines for a
// harness, used by the golden snapshot test and the proving ground.
func CommandEvidence(ctx context.Context, ha registry.HarnessAgent) ([]string, error) {
	ws, cleanup, err := tempWorkspace()
	if err != nil {
		return nil, err
	}
	defer cleanup()

	cmd, err := ha.Agent.GetLaunchCommand(ctx, launchConfig(ctx, ha.Agent, ws))
	if err != nil {
		return nil, fmt.Errorf("launch: %w", err)
	}
	lines := []string{"launch:  " + strings.Join(normalizeArgv(cmd), " ")}

	restore, ok, err := ha.Agent.GetRestoreCommand(ctx, restoreConfig(ws))
	if err != nil {
		return nil, fmt.Errorf("restore: %w", err)
	}
	if ok {
		lines = append(lines, "restore: "+strings.Join(normalizeArgv(restore), " "))
	} else {
		lines = append(lines, "restore: (not supported)")
	}
	return lines, nil
}

// --- inputs -----------------------------------------------------------------

func launchConfig(ctx context.Context, agent ports.Agent, ws string) ports.LaunchConfig {
	return ports.LaunchConfig{
		Config:        fillRequiredConfig(ctx, agent),
		Permissions:   ports.PermissionModeDefault,
		Prompt:        evalPrompt,
		SessionID:     evalSessionID,
		WorkspacePath: ws,
	}
}

func hookConfig(ws string) ports.WorkspaceHookConfig {
	return ports.WorkspaceHookConfig{
		DataDir:       filepath.Join(ws, ".aoeval-data"),
		SessionID:     evalSessionID,
		WorkspacePath: ws,
	}
}

func restoreConfig(ws string) ports.RestoreConfig {
	return ports.RestoreConfig{
		Permissions: ports.PermissionModeBypassPermissions,
		Session: ports.SessionRef{
			ID:            evalSessionID,
			WorkspacePath: ws,
			Metadata:      map[string]string{ports.MetadataKeyAgentSessionID: evalAgentSessionID},
		},
	}
}

// fillRequiredConfig populates every required config field an adapter declares
// with a typed placeholder, so a launch check isn't a false Fail just because
// the adapter requires a key the rig didn't set.
func fillRequiredConfig(ctx context.Context, agent ports.Agent) ports.AgentConfig {
	cfg := ports.AgentConfig{}
	spec, err := agent.GetConfigSpec(ctx)
	if err != nil {
		return cfg
	}
	for _, f := range spec.Fields {
		if !f.Required {
			continue
		}
		switch f.Type {
		case ports.ConfigFieldBool:
			cfg[f.Key] = true
		case ports.ConfigFieldNumber:
			cfg[f.Key] = 1
		case ports.ConfigFieldStringList:
			cfg[f.Key] = []string{"aoeval"}
		case ports.ConfigFieldEnum:
			if len(f.Enum) > 0 {
				cfg[f.Key] = f.Enum[0]
			} else {
				cfg[f.Key] = "aoeval"
			}
		default:
			cfg[f.Key] = "aoeval"
		}
	}
	return cfg
}

// --- filesystem helpers -----------------------------------------------------

func tempWorkspace() (path string, cleanup func(), err error) {
	dir, err := os.MkdirTemp("", "aoeval-ws-")
	if err != nil {
		return "", func() {}, err
	}
	return dir, func() { _ = os.RemoveAll(dir) }, nil
}

func scanInstalledTokens(ws string) (map[string]bool, error) {
	tokens := map[string]bool{}
	err := filepath.WalkDir(ws, func(path string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if d.IsDir() {
			return nil
		}
		data, rerr := os.ReadFile(path) //nolint:gosec // path from our own temp worktree walk
		if rerr != nil {
			return nil // unreadable file: skip, don't fail the scan.
		}
		for _, m := range aoHooksTokenRe.FindAllSubmatch(data, -1) {
			tokens[string(m[1])] = true
		}
		return nil
	})
	return tokens, err
}

func snapshotTree(ws string) (map[string]string, error) {
	snap := map[string]string{}
	err := filepath.WalkDir(ws, func(path string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if d.IsDir() {
			return nil
		}
		data, rerr := os.ReadFile(path) //nolint:gosec // path from our own temp worktree walk
		if rerr != nil {
			return rerr
		}
		rel, rerr := filepath.Rel(ws, path)
		if rerr != nil {
			return rerr
		}
		sum := sha256.Sum256(data)
		snap[rel] = hex.EncodeToString(sum[:])
		return nil
	})
	return snap, err
}

func sameSnapshot(a, b map[string]string) bool {
	if len(a) != len(b) {
		return false
	}
	for k, v := range a {
		if b[k] != v {
			return false
		}
	}
	return true
}

func toSet(m map[string]string) map[string]bool {
	out := make(map[string]bool, len(m))
	for k := range m {
		out[k] = true
	}
	return out
}

// --- argv helpers -----------------------------------------------------------

// normalizeArgv replaces argv[0] (which may be an absolute, machine-specific
// binary path resolved off PATH) with its basename, so evidence and golden
// snapshots are stable across machines.
func normalizeArgv(cmd []string) []string {
	if len(cmd) == 0 {
		return cmd
	}
	out := append([]string(nil), cmd...)
	out[0] = filepath.Base(out[0])
	return out
}

// isMultisetSubset reports whether every token in sub appears in super at least
// as many times (so default ⊆ mode means default adds no permission flag).
func isMultisetSubset(sub, super []string) bool {
	cnt := map[string]int{}
	for _, t := range super {
		cnt[t]++
	}
	for _, t := range sub {
		if cnt[t] == 0 {
			return false
		}
		cnt[t]--
	}
	return true
}

// tokensAdded returns the multiset of tokens present in mode but not in base.
func tokensAdded(base, mode []string) []string {
	cnt := map[string]int{}
	for _, t := range base {
		cnt[t]++
	}
	var added []string
	for _, t := range mode {
		if cnt[t] > 0 {
			cnt[t]--
			continue
		}
		added = append(added, t)
	}
	return added
}

// tokensRemoved returns tokens present in base but not in mode.
func tokensRemoved(mode, base []string) []string {
	return tokensAdded(mode, base)
}

func sortedKeys(m map[string]bool) []string {
	out := make([]string, 0, len(m))
	for k := range m {
		out = append(out, k)
	}
	sort.Strings(out)
	return out
}

func fail(r Result, format string, args ...any) Result {
	r.Status = StatusFail
	r.Detail = fmt.Sprintf(format, args...)
	return r
}

