// Stage drives the sibling Zellij pane where demonstrations run. The control
// deck types commands into it with `zellij action paste` + `send-keys Enter`,
// targeting the pane by id so the deck never has to surrender focus. Discovery
// matches the pane the layout names "stage" (the same title-match the runtime
// adapter uses for its "agent" pane).
//
// Outside Zellij (Available()==false) every method is a graceful no-op, so the
// deck still runs as a plain matrix viewer for development.
type Stage struct {
	session string
	paneID  string
	run     zellijRunner
}

// zellijRunner executes a `zellij` invocation; injectable so the deck can be
// tested without a live multiplexer.
type zellijRunner func(ctx context.Context, args ...string) ([]byte, error)

// paneInfo mirrors the fields the deck needs from `zellij action list-panes
// --json` (see internal/adapters/runtime/zellij: the same shape and title match).
type paneInfo struct {
	ID       int    `json:"id"`
	IsPlugin bool   `json:"is_plugin"`
	Title    string `json:"title"`
}

const (
	stagePaneTitle = "stage"
	deckPaneTitle  = "deck"
)

// NewStage discovers the stage pane in the current Zellij session, if any.
func NewStage(ctx context.Context) *Stage {
	return newStage(ctx, os.Getenv("ZELLIJ_SESSION_NAME"), execZellij)
}

func newStage(ctx context.Context, session string, run zellijRunner) *Stage {
	s := &Stage{session: session, run: run}
	if s.session != "" {
		s.paneID = s.discoverStagePane(ctx)
	}
	return s
}

// Available reports whether the deck is running inside Zellij with a stage pane
// it can drive.
func (s *Stage) Available() bool { return s != nil && s.session != "" && s.paneID != "" }

// PaneID returns the discovered stage pane id (empty when unavailable).
func (s *Stage) PaneID() string {
	if s == nil {
		return ""
	}
	return s.paneID
}

// Run types command into the stage pane and presses Enter, so the audience
// watches it execute live. It is a no-op when no stage is available.
func (s *Stage) Run(ctx context.Context, command string) error {
	if !s.Available() {
		return nil
	}
	if _, err := s.run(ctx, "--session", s.session, "action", "paste", "--pane-id", s.paneID, command); err != nil {
		return fmt.Errorf("stage paste: %w", err)
	}
	if _, err := s.run(ctx, "--session", s.session, "action", "send-keys", "--pane-id", s.paneID, "Enter"); err != nil {
		return fmt.Errorf("stage enter: %w", err)
	}
	return nil
}

// Clear blanks the stage pane (best effort), so each demonstration starts fresh.
func (s *Stage) Clear(ctx context.Context) error {
	return s.Run(ctx, "clear")
}

func (s *Stage) discoverStagePane(ctx context.Context) string {
	out, err := s.run(ctx, "--session", s.session, "action", "list-panes", "--all", "--json")
	if err != nil {
		return ""
	}
	var panes []paneInfo
	if err := json.Unmarshal(out, &panes); err != nil {
		return ""
	}
	// Prefer the pane the layout titled "stage"; fall back to any non-plugin,
	// non-"deck" pane so a renamed layout still works.
