	for _, p := range panes {
		if p.IsPlugin {
			continue
		}
		if p.Title == stagePaneTitle {
			return fmt.Sprintf("terminal_%d", p.ID)
		}
		if p.Title != deckPaneTitle && fallback == "" {
			fallback = fmt.Sprintf("terminal_%d", p.ID)
		}
	}
	return fallback
}

func execZellij(ctx context.Context, args ...string) ([]byte, error) {
