package evalrig

import (
	"fmt"
	"strings"

	"github.com/charmbracelet/lipgloss"

	"github.com/aoagents/agent-orchestrator/backend/internal/adapters/agent/conformance"
)

const (
	harnessW = 16
	dimW     = 6
)

var (
	colGreen  = lipgloss.Color("42")
	colRed    = lipgloss.Color("203")
	colOrange = lipgloss.Color("214")
	colYellow = lipgloss.Color("220")
	colGray   = lipgloss.Color("245")
	colDim    = lipgloss.Color("240")
	colCyan   = lipgloss.Color("44")

	titleStyle   = lipgloss.NewStyle().Bold(true).Foreground(colCyan)
	headerStyle  = lipgloss.NewStyle().Bold(true).Foreground(colGray)
	harnessStyle = lipgloss.NewStyle().Foreground(colGray)
	harnessSel   = lipgloss.NewStyle().Bold(true).Foreground(colCyan)
	panelStyle   = lipgloss.NewStyle().Border(lipgloss.RoundedBorder()).BorderForeground(colDim).Padding(0, 1)
	logStyle     = lipgloss.NewStyle().Foreground(colDim)
	footerStyle  = lipgloss.NewStyle().Foreground(colGray)
)

// dimShort maps a dimension id to a fixed-width column label.
var dimShort = map[string]string{
	conformance.DimSpawn:       "SPAWN",
	conformance.DimActivity:    "ACT",
	conformance.DimSessionInfo: "INFO",
	conformance.DimPermissions: "PERM",
	conformance.DimHooks:       "HOOK",
	conformance.DimCommands:    "CMD",
}

// View implements tea.Model.
func (m Model) View() string {
	if m.quitting {
		return ""
	}
	var b strings.Builder

	fmt.Fprintf(&b, "%s   %s\n\n", titleStyle.Render("AO Adapter Proving Ground"), stageBadge(m.stage))

	// Column header.
	b.WriteString(headerStyle.Width(harnessW).Render("HARNESS"))
	for _, d := range m.dims {
		b.WriteString(headerStyle.Width(dimW).Align(lipgloss.Center).Render(dimShort[d]))
	}
	b.WriteString("\n")

	// Matrix rows.
	for r, ha := range m.harnessed {
		h := string(ha.Harness)
		nameStyle := harnessStyle
		if r == m.row {
			nameStyle = harnessSel
		}
		b.WriteString(nameStyle.Width(harnessW).Render(truncate(h, harnessW-1)))
		for c, d := range m.dims {
			b.WriteString(renderCell(m.state[h][d], m.result[h][d].Status, r == m.row && c == m.col))
		}
		b.WriteString("\n")
	}

	b.WriteString("\n")
	b.WriteString(m.detailPanel())
	b.WriteString("\n")
	if len(m.logs) > 0 {
		b.WriteString(logStyle.Render(strings.Join(m.logs, "\n")))
		b.WriteString("\n")
	}
	b.WriteString(footerStyle.Render(
		"enter run+next · space/r re-run · a run row · A run all · ↑↓←→ / hjkl move · q quit"))
	b.WriteString("\n")
	return b.String()
}

func (m Model) detailPanel() string {
	ha := m.harnessed[m.row]
	h := string(ha.Harness)
	d := m.dims[m.col]
	title := fmt.Sprintf("▸ %s / %s", h, d)

	switch m.state[h][d] {
	case cellRunning:
		return panelStyle.Render(title + "   " + lipgloss.NewStyle().Foreground(colYellow).Render("running…") +
			"\n" + lipgloss.NewStyle().Foreground(colDim).Render(goTestCommand(h, d)))
	case cellDone:
		res := m.result[h][d]
		lines := []string{title + "   " + statusBadge(res.Status), res.Detail}
		lines = append(lines, res.Evidence...)
		return panelStyle.Render(strings.Join(lines, "\n"))
	default: // cellPending
		return panelStyle.Render(title + "   " + lipgloss.NewStyle().Foreground(colDim).Render("(not run)") +
			"\n" + lipgloss.NewStyle().Foreground(colDim).Render(goTestCommand(h, d)))
	}
}

func renderCell(state cellState, status conformance.Status, selected bool) string {
	glyph, col := cellGlyph(state, status)
	s := lipgloss.NewStyle().Width(dimW).Align(lipgloss.Center).Foreground(col)
	if selected {
		s = s.Reverse(true).Bold(true)
	}
	return s.Render(glyph)
}

func cellGlyph(state cellState, status conformance.Status) (string, lipgloss.Color) {
	switch state {
	case cellRunning:
		return "•", colYellow
	case cellDone:
		switch status {
		case conformance.StatusPass:
			return "✓", colGreen
		case conformance.StatusFail:
			return "✗", colRed
		case conformance.StatusGap:
			return "▲", colOrange
		case conformance.StatusSkip:
			return "–", colDim
		}
	}
	return "·", colDim
}

func statusBadge(status conformance.Status) string {
	col := colDim
	switch status {
	case conformance.StatusPass:
		col = colGreen
	case conformance.StatusFail:
		col = colRed
	case conformance.StatusGap:
		col = colOrange
	case conformance.StatusSkip:
		col = colGray
	}
	return lipgloss.NewStyle().Bold(true).Foreground(col).Render(strings.ToUpper(string(status)))
}

func stageBadge(s *Stage) string {
	if s.Available() {
		return lipgloss.NewStyle().Foreground(colGreen).Render("● stage: "+s.PaneID())
	}
	return lipgloss.NewStyle().Foreground(colDim).Render("○ stage: none (matrix-only)")
}

func truncate(s string, max int) string {
	if max <= 0 {
		return ""
	}
	r := []rune(s)
	if len(r) <= max {
		return s
	}
	if max == 1 {
		return "…"
	}
	return string(r[:max-1]) + "…"
}

toolUseResult.originalFile:
// Package evalrig is the interactive control deck of the AO Adapter Proving
// Ground: a Bubble Tea TUI that renders the adapters × six-dimensions eval
// matrix and lets a presenter run cells one keypress at a time, driving a
// sibling Zellij "stage" pane to show each check executing live. The verdicts
// come from the same in-process conformance engine CI runs, so the demo and the
// regression guard can never disagree.
package evalrig

import (
	"context"
	"fmt"
	"strings"

	tea "github.com/charmbracelet/bubbletea"
	"github.com/charmbracelet/lipgloss"

	"github.com/aoagents/agent-orchestrator/backend/internal/adapters/agent/conformance"
	"github.com/aoagents/agent-orchestrator/backend/internal/adapters/agent/registry"
)

type cellState int

const (
	cellPending cellState = iota
	cellRunning
	cellDone
)

// Model is the control-deck state.
type Model struct {
	harnessed []registry.HarnessAgent
	dims      []string
	state     map[string]map[string]cellState
	result    map[string]map[string]conformance.Result
	row, col  int
	logs      []string
	stage     *Stage
	width     int
	quitting  bool
}

// cellResultMsg carries a finished cell verdict back into Update.
type cellResultMsg struct {
	harness string
	dim     string
	result  conformance.Result
}

// New builds the deck over the registered adapters and a (possibly no-op) stage.
func New(stage *Stage) Model {
	harnessed := registry.Harnessed()
	state := make(map[string]map[string]cellState, len(harnessed))
	result := make(map[string]map[string]conformance.Result, len(harnessed))
	for _, ha := range harnessed {
		h := string(ha.Harness)
		state[h] = map[string]cellState{}
		result[h] = map[string]conformance.Result{}
		for _, d := range conformance.Dimensions {
			state[h][d] = cellPending
		}
	}
	return Model{
		harnessed: harnessed,
		dims:      conformance.Dimensions,
		state:     state,
		result:    result,
		stage:     stage,
	}
}

// Init implements tea.Model.
func (m Model) Init() tea.Cmd { return nil }

// Update implements tea.Model.
func (m Model) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	switch msg := msg.(type) {
	case tea.WindowSizeMsg:
		m.width = msg.Width
		return m, nil

	case cellResultMsg:
		m.state[msg.harness][msg.dim] = cellDone
		m.result[msg.harness][msg.dim] = msg.result
		m.appendLog(fmt.Sprintf("%s/%s → %s", msg.harness, msg.dim, strings.ToUpper(string(msg.result.Status))))
		return m, nil

	case tea.KeyMsg:
		return m.handleKey(msg)
	}
	return m, nil
}

func (m Model) handleKey(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
	switch msg.String() {
	case "q", "ctrl+c", "esc":
		m.quitting = true
		return m, tea.Quit
	case "up", "k":
		m.row = clamp(m.row-1, 0, len(m.harnessed)-1)
	case "down", "j":
		m.row = clamp(m.row+1, 0, len(m.harnessed)-1)
	case "left", "h":
		m.col = clamp(m.col-1, 0, len(m.dims)-1)
	case "right", "l":
		m.col = clamp(m.col+1, 0, len(m.dims)-1)
	case "enter":
		// Run the selected cell, then advance to the next — the "keep pressing
		// enter to run the next test" presenter flow.
		cmd := m.runSelected()
		m.advance()
		return m, cmd
	case " ", "r":
		return m, m.runSelected()
	case "a":
		// Run every dimension for the current adapter.
		return m, m.runRow(m.row)
	case "A":
		// Run the whole matrix.
		return m, m.runAll()
	}
	return m, nil
}

func (m *Model) runSelected() tea.Cmd {
	return m.runCell(m.row, m.col)
}

func (m *Model) runCell(row, col int) tea.Cmd {
	ha := m.harnessed[row]
	h := string(ha.Harness)
	dim := m.dims[col]
	if m.state[h][dim] == cellRunning {
		return nil
	}
	m.state[h][dim] = cellRunning
	m.appendLog(fmt.Sprintf("running %s/%s …", h, dim))
	stage := m.stage
	return func() tea.Msg {
		ctx := context.Background()
		// Show the real test executing on stage (best effort), then compute the
		// authoritative verdict in-process.
		_ = stage.Run(ctx, goTestCommand(h, dim))
		res, _ := conformance.RunDimension(ctx, ha, dim)
		return cellResultMsg{harness: h, dim: dim, result: res}
	}
}

func (m *Model) runRow(row int) tea.Cmd {
	cmds := make([]tea.Cmd, 0, len(m.dims))
	for c := range m.dims {
		if cmd := m.runCell(row, c); cmd != nil {
			cmds = append(cmds, cmd)
		}
	}
	return tea.Batch(cmds...)
}

func (m *Model) runAll() tea.Cmd {
	cmds := make([]tea.Cmd, 0, len(m.harnessed)*len(m.dims))
	for r := range m.harnessed {
		for c := range m.dims {
			if cmd := m.runCell(r, c); cmd != nil {
				cmds = append(cmds, cmd)
			}
		}
	}
	return tea.Batch(cmds...)
}

// advance moves the cursor to the next cell, left-to-right then down a row.
func (m *Model) advance() {
	m.col++
	if m.col >= len(m.dims) {
		m.col = 0
		if m.row < len(m.harnessed)-1 {
			m.row++
		} else {
			m.col = len(m.dims) - 1 // stay on the last cell
		}
	}
}

func (m *Model) appendLog(line string) {
	m.logs = append(m.logs, line)
	if len(m.logs) > 6 {
		m.logs = m.logs[len(m.logs)-6:]
	}
}

// goTestCommand is the command the stage runs to demonstrate one cell: the real
// conformance subtest, in verbose mode, so the audience sees genuine PASS lines.
func goTestCommand(harness, dim string) string {
	return fmt.Sprintf(
		"go test ./internal/adapters/agent/conformance/ -run 'TestConformance/%s/%s' -v -count=1",
		harness, dim,
	)
}

func clamp(v, lo, hi int) int {
	if v < lo {
		return lo
	}
	if v > hi {
		return hi
	}
	return v
}

// Package cli implements the user-facing ao command. It stays thin: commands
// discover the local daemon, call its loopback HTTP API, and format output.
package cli

import (
	"context"
	"errors"
	"io"
	"net/http"
	"os"
	"os/exec"
	"time"

	"github.com/spf13/cobra"

	"github.com/aoagents/agent-orchestrator/backend/internal/daemon"
	"github.com/aoagents/agent-orchestrator/backend/internal/processalive"
)

// Execute runs the ao CLI with process stdio.
func Execute() error {
	return NewRootCommand(DefaultDeps()).Execute()
}

// usageError marks a command-line misuse (bad flag, wrong arg count). It lets
// the process entrypoint return exit code 2 for usage errors versus 1 for
// runtime failures, matching the convention CLIs are scripted against.
type usageError struct{ err error }

func (e usageError) Error() string { return e.err.Error() }
func (e usageError) Unwrap() error { return e.err }

// ExitCode maps a CLI error to a process exit code: 2 for usage errors, 1 for
// any other failure, 0 for success.
func ExitCode(err error) int {
	if err == nil {
		return 0
	}
	var ue usageError
	if errors.As(err, &ue) {
		return 2
	}
	return 1
}

// Deps holds the small set of side effects the CLI needs. Tests replace these
// functions without reaching into process-global state.
type Deps struct {
	In  io.Reader
	Out io.Writer
	Err io.Writer

	HTTPClient    *http.Client
	Executable    func() (string, error)
	StartProcess  func(processStartConfig) error
	ProcessAlive  func(pid int) bool
	LookPath      func(file string) (string, error)
	CommandOutput func(ctx context.Context, name string, args ...string) ([]byte, error)
	// DoctorGitHubRESTBase lets tests point the doctor GitHub token probe at
	// httptest without mutating package-global state.
	DoctorGitHubRESTBase string
	Now                  func() time.Time
	Sleep                func(time.Duration)
}

// DefaultDeps returns production dependencies.
func DefaultDeps() Deps {
	return Deps{
		In:                   os.Stdin,
		Out:                  os.Stdout,
		Err:                  os.Stderr,
		HTTPClient:           &http.Client{Timeout: 2 * time.Second},
		Executable:           os.Executable,
		StartProcess:         startProcess,
		ProcessAlive:         processalive.Alive,
		LookPath:             exec.LookPath,
		CommandOutput:        commandOutput,
		DoctorGitHubRESTBase: defaultDoctorGitHubRESTBase,
		Now:                  time.Now,
		Sleep:                time.Sleep,
	}
}

func commandOutput(ctx context.Context, name string, args ...string) ([]byte, error) {
	return exec.CommandContext(ctx, name, args...).CombinedOutput()
}

func (d Deps) withDefaults() Deps {
	def := DefaultDeps()
	if d.In == nil {
		d.In = def.In
	}
	if d.Out == nil {
		d.Out = def.Out
	}
	if d.Err == nil {
		d.Err = def.Err
	}
	if d.HTTPClient == nil {
		d.HTTPClient = def.HTTPClient
	}
	if d.Executable == nil {
		d.Executable = def.Executable
	}
	if d.StartProcess == nil {
		d.StartProcess = def.StartProcess
	}
	if d.ProcessAlive == nil {
		d.ProcessAlive = def.ProcessAlive
	}
	if d.LookPath == nil {
		d.LookPath = def.LookPath
	}
	if d.CommandOutput == nil {
		d.CommandOutput = def.CommandOutput
	}
	if d.DoctorGitHubRESTBase == "" {
		d.DoctorGitHubRESTBase = def.DoctorGitHubRESTBase
	}
	if d.Now == nil {
		d.Now = def.Now
	}
	if d.Sleep == nil {
		d.Sleep = def.Sleep
	}
	return d
}

// NewRootCommand builds a testable root command.
func NewRootCommand(deps Deps) *cobra.Command {
	deps = deps.withDefaults()
	ctx := &commandContext{deps: deps}

	root := &cobra.Command{
		Use:           "ao",
		Short:         "Agent Orchestrator",
		Long:          "Agent Orchestrator manages the local daemon that supervises parallel coding-agent sessions.",
		Version:       VersionString(),
		SilenceUsage:  true,
		SilenceErrors: true,
	}
	root.SetIn(deps.In)
	root.SetOut(deps.Out)
	root.SetErr(deps.Err)
	root.CompletionOptions.DisableDefaultCmd = true
	// Tag flag-parse failures as usage errors so the entrypoint can exit 2 for
	// misuse versus 1 for runtime failures. Subcommands inherit this func.
	root.SetFlagErrorFunc(func(_ *cobra.Command, err error) error {
		return usageError{err}
	})

	root.AddCommand(newDaemonCommand())
	root.AddCommand(newStartCommand(ctx))
	root.AddCommand(newStopCommand(ctx))
	root.AddCommand(newStatusCommand(ctx))
	root.AddCommand(newDoctorCommand(ctx))
	root.AddCommand(newSpawnCommand(ctx))
	root.AddCommand(newSendCommand(ctx))
	root.AddCommand(newHooksCommand(ctx))
	root.AddCommand(newProjectCommand(ctx))
	root.AddCommand(newSessionCommand(ctx))
	root.AddCommand(newOrchestratorCommand(ctx))
	root.AddCommand(newCompletionCommand())
	root.AddCommand(newVersionCommand())

	return root
}

type commandContext struct {
	deps Deps
}

func noArgs(cmd *cobra.Command, args []string) error {
	if err := cobra.ExactArgs(0)(cmd, args); err != nil {
		return usageError{err}
	}
	return nil
}

func newDaemonCommand() *cobra.Command {
	return &cobra.Command{
		Use:    "daemon",
		Short:  "Run the AO backend daemon",
		Hidden: true,
		Args:   noArgs,
		RunE: func(cmd *cobra.Command, args []string) error {
			return daemon.Run()
		},
	}
}

