package evalrig

import (
	"context"
	"slices"
	"strings"
	"testing"

	tea "github.com/charmbracelet/bubbletea"

	"github.com/aoagents/agent-orchestrator/backend/internal/adapters/agent/conformance"
)

// fakeZellij records the args of every zellij invocation and answers list-panes
// with a fixed JSON payload.
type fakeZellij struct {
	listJSON string
	calls    [][]string
}

func (f *fakeZellij) run(_ context.Context, args ...string) ([]byte, error) {
	f.calls = append(f.calls, args)
	if len(args) >= 4 && args[3] == "list-panes" {
		return []byte(f.listJSON), nil
	}
	return nil, nil
}

func TestStageDiscoversPaneByTitle(t *testing.T) {
	f := &fakeZellij{listJSON: `[
		{"id":0,"is_plugin":false,"title":"deck"},
		{"id":1,"is_plugin":true,"title":"stage"},
		{"id":2,"is_plugin":false,"title":"stage"}
	]`}
	s := newStage(context.Background(), "sess-1", f.run)
	if !s.Available() {
		t.Fatalf("Available() = false, want true")
	}
	// The non-plugin "stage" pane (id 2) wins over the plugin one (id 1).
	if s.PaneID() != "terminal_2" {
		t.Fatalf("PaneID() = %q, want terminal_2", s.PaneID())
	}

	if err := s.Run(context.Background(), "go test ./..."); err != nil {
		t.Fatalf("Run: %v", err)
	}
	// Last two calls must be a paste of the command, then an Enter, both
	// targeting the discovered pane id.
	paste := s.lastCallWith(f, "paste")
	if paste == nil || paste[len(paste)-1] != "go test ./..." {
		t.Fatalf("paste call = %v", paste)
	}
	if !slices.Contains(paste, "--pane-id") || !slices.Contains(paste, "terminal_2") {
		t.Fatalf("paste did not target the stage pane: %v", paste)
	}
	enter := s.lastCallWith(f, "send-keys")
	if enter == nil || enter[len(enter)-1] != "Enter" {
		t.Fatalf("send-keys call = %v", enter)
	}
}

func TestStageFallsBackToNonDeckPane(t *testing.T) {
	// No pane titled "stage": fall back to the first non-plugin, non-deck pane.
	f := &fakeZellij{listJSON: `[
		{"id":0,"is_plugin":false,"title":"deck"},
		{"id":7,"is_plugin":false,"title":"scratch"}
	]`}
	s := newStage(context.Background(), "sess-1", f.run)
	if s.PaneID() != "terminal_7" {
		t.Fatalf("PaneID() = %q, want terminal_7 (fallback)", s.PaneID())
	}
}

func TestStageNoopWithoutSession(t *testing.T) {
	f := &fakeZellij{}
	s := newStage(context.Background(), "", f.run)
	if s.Available() {
		t.Fatalf("Available() = true without a session")
	}
	if err := s.Run(context.Background(), "echo hi"); err != nil {
		t.Fatalf("Run no-op: %v", err)
	}
	if len(f.calls) != 0 {
		t.Fatalf("expected no zellij calls without a session, got %v", f.calls)
	}
}

func (s *Stage) lastCallWith(f *fakeZellij, action string) []string {
	var found []string
	for _, c := range f.calls {
		if len(c) >= 4 && c[3] == action {
			found = c
		}
	}
	return found
}

// noopStage is a Stage that is never "available", so the deck runs matrix-only.
func noopStage() *Stage { return &Stage{} }

func TestModelRunCellComputesVerdict(t *testing.T) {
	m := New(noopStage())
	if len(m.harnessed) == 0 {
		t.Fatal("no adapters")
	}
	// Default cursor is the first adapter / first dimension (spawn). Pressing
	// enter runs that cell and advances the cursor.
	updated, cmd := m.Update(tea.KeyMsg{Type: tea.KeyEnter})
	m = updated.(Model)
	if cmd == nil {
		t.Fatal("enter produced no command")
	}
	h := string(m.harnessed[0].Harness)
	if m.state[h][conformance.DimSpawn] != cellRunning {
		t.Fatalf("selected cell state = %v, want running", m.state[h][conformance.DimSpawn])
	}
	if m.col != 1 {
		t.Fatalf("cursor did not advance: col = %d, want 1", m.col)
	}

	// Execute the command to get the verdict, then feed it back.
	msg := cmd()
	res, ok := msg.(cellResultMsg)
	if !ok {
		t.Fatalf("command returned %T, want cellResultMsg", msg)
	}
	updated, _ = m.Update(res)
	m = updated.(Model)
	if m.state[h][conformance.DimSpawn] != cellDone {
		t.Fatalf("cell state after result = %v, want done", m.state[h][conformance.DimSpawn])
	}
	if got := m.result[h][conformance.DimSpawn].Status; got != conformance.StatusPass {
		t.Fatalf("spawn verdict = %q, want pass", got)
	}
}

func TestModelNavigationClamps(t *testing.T) {
	m := New(noopStage())
	// Up/left at the origin must not go negative.
	up, _ := m.Update(tea.KeyMsg{Type: tea.KeyUp})
	left, _ := up.(Model).Update(tea.KeyMsg{Type: tea.KeyLeft})
	m = left.(Model)
	if m.row != 0 || m.col != 0 {
		t.Fatalf("clamp failed: row=%d col=%d", m.row, m.col)
	}
}

func TestModelViewRenders(t *testing.T) {
	m := New(noopStage())
	out := m.View()
	for _, want := range []string{"AO Adapter Proving Ground", "HARNESS", "SPAWN", string(m.harnessed[0].Harness), "matrix-only"} {
		if !strings.Contains(stripANSI(out), want) {
			t.Fatalf("view missing %q\n---\n%s", want, stripANSI(out))
		}
	}
}

// stripANSI removes ANSI escape sequences so assertions match the visible text.
func stripANSI(s string) string {
	var b strings.Builder
	inEsc := false
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c == 0x1b {
			inEsc = true
			continue
		}
		if inEsc {
			if (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') {
				inEsc = false
			}
			continue
		}
		b.WriteByte(c)
	}
	return b.String()
}

package evalrig

import (
	"fmt"
	"strings"

	"github.com/charmbracelet/lipgloss"

	"github.com/aoagents/agent-orchestrator/backend/internal/adapters/agent/conformance"
)

const (
	harnessW = 16
	dimW     = 6
)

var (
	colGreen  = lipgloss.Color("42")
	colRed    = lipgloss.Color("203")
	colOrange = lipgloss.Color("214")
	colYellow = lipgloss.Color("220")
	colGray   = lipgloss.Color("245")
	colDim    = lipgloss.Color("240")
	colCyan   = lipgloss.Color("44")

	titleStyle   = lipgloss.NewStyle().Bold(true).Foreground(colCyan)
	headerStyle  = lipgloss.NewStyle().Bold(true).Foreground(colGray)
	harnessStyle = lipgloss.NewStyle().Foreground(colGray)
	harnessSel   = lipgloss.NewStyle().Bold(true).Foreground(colCyan)
	panelStyle   = lipgloss.NewStyle().Border(lipgloss.RoundedBorder()).BorderForeground(colDim).Padding(0, 1)
	logStyle     = lipgloss.NewStyle().Foreground(colDim)
	footerStyle  = lipgloss.NewStyle().Foreground(colGray)
)

// dimShort maps a dimension id to a fixed-width column label.
var dimShort = map[string]string{
	conformance.DimSpawn:       "SPAWN",
	conformance.DimActivity:    "ACT",
	conformance.DimSessionInfo: "INFO",
	conformance.DimPermissions: "PERM",
	conformance.DimHooks:       "HOOK",
	conformance.DimCommands:    "CMD",
}

// View implements tea.Model.
func (m Model) View() string {
	if m.quitting {
		return ""
	}
	var b strings.Builder

	fmt.Fprintf(&b, "%s   %s\n\n", titleStyle.Render("AO Adapter Proving Ground"), stageBadge(m.stage))

	// Column header.
	b.WriteString(headerStyle.Width(harnessW).Render("HARNESS"))
	for _, d := range m.dims {
		b.WriteString(headerStyle.Width(dimW).Align(lipgloss.Center).Render(dimShort[d]))
	}
	b.WriteString("\n")

	// Matrix rows.
	for r, ha := range m.harnessed {
		h := string(ha.Harness)
		nameStyle := harnessStyle
		if r == m.row {
			nameStyle = harnessSel
		}
		b.WriteString(nameStyle.Width(harnessW).Render(truncate(h, harnessW-1)))
		for c, d := range m.dims {
			b.WriteString(renderCell(m.state[h][d], m.result[h][d].Status, r == m.row && c == m.col))
		}
		b.WriteString("\n")
	}

	b.WriteString("\n")
	b.WriteString(m.detailPanel())
	b.WriteString("\n")
	if len(m.logs) > 0 {
		b.WriteString(logStyle.Render(strings.Join(m.logs, "\n")))
		b.WriteString("\n")
	}
	b.WriteString(footerStyle.Render(
		"enter run+next · space/r re-run · a run row · A run all · ↑↓←→ / hjkl move · q quit"))
	b.WriteString("\n")
	return b.String()
}

func (m Model) detailPanel() string {
	ha := m.harnessed[m.row]
	h := string(ha.Harness)
	d := m.dims[m.col]
	title := fmt.Sprintf("▸ %s / %s", h, d)

	switch m.state[h][d] {
	case cellRunning:
		return panelStyle.Render(title + "   " + lipgloss.NewStyle().Foreground(colYellow).Render("running…") +
			"\n" + lipgloss.NewStyle().Foreground(colDim).Render(goTestCommand(h, d)))
	case cellDone:
		res := m.result[h][d]
		lines := make([]string, 0, 2+len(res.Evidence))
		lines = append(lines, title+"   "+statusBadge(res.Status), res.Detail)
		lines = append(lines, res.Evidence...)
		return panelStyle.Render(strings.Join(lines, "\n"))
	default: // cellPending
		return panelStyle.Render(title + "   " + lipgloss.NewStyle().Foreground(colDim).Render("(not run)") +
			"\n" + lipgloss.NewStyle().Foreground(colDim).Render(goTestCommand(h, d)))
	}
}

func renderCell(state cellState, status conformance.Status, selected bool) string {
	glyph, col := cellGlyph(state, status)
	s := lipgloss.NewStyle().Width(dimW).Align(lipgloss.Center).Foreground(col)
	if selected {
		s = s.Reverse(true).Bold(true)
	}
	return s.Render(glyph)
}

func cellGlyph(state cellState, status conformance.Status) (string, lipgloss.Color) {
	switch state {
	case cellRunning:
		return "•", colYellow
	case cellDone:
		switch status {
		case conformance.StatusPass:
			return "✓", colGreen
		case conformance.StatusFail:
			return "✗", colRed
		case conformance.StatusGap:
			return "▲", colOrange
		case conformance.StatusSkip:
			return "–", colDim
		}
	}
	return "·", colDim
}

func statusBadge(status conformance.Status) string {
	col := colDim
	switch status {
	case conformance.StatusPass:
		col = colGreen
	case conformance.StatusFail:
		col = colRed
	case conformance.StatusGap:
		col = colOrange
	case conformance.StatusSkip:
		col = colGray
	}
	return lipgloss.NewStyle().Bold(true).Foreground(col).Render(strings.ToUpper(string(status)))
}

func stageBadge(s *Stage) string {
	if s.Available() {
		return lipgloss.NewStyle().Foreground(colGreen).Render("● stage: " + s.PaneID())
	}
	return lipgloss.NewStyle().Foreground(colDim).Render("○ stage: none (matrix-only)")
}

func truncate(s string, maxLen int) string {
	if maxLen <= 0 {
		return ""
	}
	r := []rune(s)
	if len(r) <= maxLen {
		return s
	}
	if maxLen == 1 {
		return "…"
	}
	return string(r[:maxLen-1]) + "…"
}

