		nameStyle := harnessStyle
		if r == m.row {
			nameStyle = harnessSel
		}
		b.WriteString(nameStyle.Width(harnessW).Render(truncate(h, harnessW-1)))
		for c, d := range m.dims {
			b.WriteString(renderCell(m.state[h][d], m.result[h][d].Status, r == m.row && c == m.col))
		}
		b.WriteString("\n")
	}

	b.WriteString("\n")
	b.WriteString(m.detailPanel())
	b.WriteString("\n")
	if panel := m.livePanel(); panel != "" {
		b.WriteString(panel)
		b.WriteString("\n")
	}
	if len(m.logs) > 0 {
		b.WriteString(logStyle.Render(strings.Join(m.logs, "\n")))
		b.WriteString("\n")
	}
	b.WriteString(footerStyle.Render(
		"enter run+next · space/r re-run · a row · A all · L live · x stop · ↑↓←→/hjkl move · q quit"))
	b.WriteString("\n")
	return b.String()
}

// livePanel renders the live session the deck is watching, if any.
func (m Model) livePanel() string {
	ls := m.liveSession
	if ls == nil {
		return ""
	}
	head := fmt.Sprintf("◆ live %s  %s", ls.harness, liveStateBadge(ls.state))
	lines := []string{head, "session: " + ls.id}
	if ls.displayName != "" {
		lines = append(lines, "title:   "+ls.displayName)
	}
	if ls.status != "" {
		lines = append(lines, "status:  "+ls.status)
	}
	if len(ls.history) > 0 {
		lines = append(lines, "activity: "+strings.Join(ls.history, " → "))
	}
	if ls.terminated {
		lines = append(lines, lipgloss.NewStyle().Foreground(colDim).Render("(session ended)"))
	}
	if ls.errText != "" {
		lines = append(lines, lipgloss.NewStyle().Foreground(colRed).Render("error: "+ls.errText))
	}
	return livePanelStyle.Render(strings.Join(lines, "\n"))
}

func liveBadge(l LiveConfig) string {
	if l.enabled() {
		return lipgloss.NewStyle().Foreground(colGreen).Render("◆ live: " + l.ProjectID)
	}
	return lipgloss.NewStyle().Foreground(colDim).Render("◇ live: off (--project)")
}

func liveStateBadge(state string) string {
	col := colGray
	switch state {
	case "active":
		col = colGreen
	case "idle":
		col = colYellow
	case "waiting_input":
		col = colOrange
	case "exited":
		col = colDim
	}
	if state == "" {
		state = "…"
	}
	return lipgloss.NewStyle().Bold(true).Foreground(col).Render(state)
}

func (m Model) detailPanel() string {
	ha := m.harnessed[m.row]
	h := string(ha.Harness)
	d := m.dims[m.col]
	title := fmt.Sprintf("▸ %s / %s", h, d)

	switch m.state[h][d] {
	case cellRunning:
		return panelStyle.Render(title + "   " + lipgloss.NewStyle().Foreground(colYellow).Render("running…") +
			"\n" + lipgloss.NewStyle().Foreground(colDim).Render(goTestCommand(h, d)))
	case cellDone:
		res := m.result[h][d]
		lines := make([]string, 0, 2+len(res.Evidence))
		lines = append(lines, title+"   "+statusBadge(res.Status), res.Detail)
		lines = append(lines, res.Evidence...)
		return panelStyle.Render(strings.Join(lines, "\n"))
	default: // cellPending
		return panelStyle.Render(title + "   " + lipgloss.NewStyle().Foreground(colDim).Render("(not run)") +
			"\n" + lipgloss.NewStyle().Foreground(colDim).Render(goTestCommand(h, d)))
	}
}

func renderCell(state cellState, status conformance.Status, selected bool) string {
	glyph, col := cellGlyph(state, status)
	s := lipgloss.NewStyle().Width(dimW).Align(lipgloss.Center).Foreground(col)
	if selected {
		s = s.Reverse(true).Bold(true)
	}
	return s.Render(glyph)
}

func cellGlyph(state cellState, status conformance.Status) (string, lipgloss.Color) {
	switch state {
	case cellRunning:
		return "•", colYellow
	case cellDone:
		switch status {
		case conformance.StatusPass:
			return "✓", colGreen
		case conformance.StatusFail:
			return "✗", colRed
		case conformance.StatusGap:
			return "▲", colOrange
		case conformance.StatusSkip:
			return "–", colDim
		}
	}
	return "·", colDim
}

func statusBadge(status conformance.Status) string {
	col := colDim
	switch status {
	case conformance.StatusPass:
		col = colGreen
	case conformance.StatusFail:
		col = colRed
	case conformance.StatusGap:
		col = colOrange
	case conformance.StatusSkip:
		col = colGray
	}
	return lipgloss.NewStyle().Bold(true).Foreground(col).Render(strings.ToUpper(string(status)))
}

func stageBadge(s *Stage) string {
	if s.Available() {
		return lipgloss.NewStyle().Foreground(colGreen).Render("● stage: " + s.PaneID())
	}
	return lipgloss.NewStyle().Foreground(colDim).Render("○ stage: none (matrix-only)")
}

func truncate(s string, maxLen int) string {
	if maxLen <= 0 {
		return ""
	}
	r := []rune(s)
	if len(r) <= maxLen {
		return s
	}
	if maxLen == 1 {
		return "…"
	}
	return string(r[:maxLen-1]) + "…"
}

