package cli

import (
	"context"

	tea "github.com/charmbracelet/bubbletea"
	"github.com/spf13/cobra"

	"github.com/aoagents/agent-orchestrator/backend/internal/cli/evalrig"
)

// daemonClientAdapter exposes the shared CLI HTTP client to the evalrig package
// as its narrow evalrig.DaemonClient, so the deck can spawn and poll live
// sessions without the evalrig package importing cli.
type daemonClientAdapter struct{ ctx *commandContext }

func (d daemonClientAdapter) Get(ctx context.Context, path string, out any) error {
	return d.ctx.getJSON(ctx, path, out)
}

func (d daemonClientAdapter) Post(ctx context.Context, path string, body, out any) error {
	return d.ctx.postJSON(ctx, path, body, out)
}

// newEvalRigCommand builds `ao evalrig`, the interactive Adapter Proving Ground.
// It renders the adapters × six-dimensions conformance matrix as a Bubble Tea
// control deck; when run inside the bundled Zellij layout it drives a sibling
// "stage" pane to show each check executing live. With --project (and a running
// daemon) the deck can also live-spawn an installed agent and watch its real
// activity and session info. Run it directly for a matrix-only viewer.
func newEvalRigCommand(ctx *commandContext) *cobra.Command {
	var (
		project string
		prompt  string
	)
	cmd := &cobra.Command{
		Use:   "evalrig",
		Short: "Interactive adapter proving ground (eval matrix demo)",
		Long: "Interactive, presenter-paced demonstration of the agent adapter " +
			"conformance matrix.\n\n" +
			"Each cell is one (adapter, dimension) check from the same engine CI " +
			"runs. Press enter to run the selected cell and advance; inside the " +
			"bundled Zellij layout the matching `go test` runs live in the stage " +
			"pane. With --project and a running daemon, press L to live-spawn the " +
			"selected agent and watch its real activity. See test/evalrig/ for the " +
			"layout and recording scripts.",
		Args: cobra.NoArgs,
		RunE: func(cmd *cobra.Command, _ []string) error {
			stage := evalrig.NewStage(cmd.Context())
			live := evalrig.LiveConfig{Prompt: prompt}
			if project != "" {
				live.Client = daemonClientAdapter{ctx: ctx}
				live.ProjectID = project
			}
			program := tea.NewProgram(evalrig.New(stage, live), tea.WithAltScreen())
			_, err := program.Run()
			return err
		},
	}
	f := cmd.Flags()
	f.StringVar(&project, "project", "", "Project id for live spawns (enables the L key; requires a running daemon)")
	f.StringVar(&prompt, "prompt", "Add a health check endpoint and a test for it.", "Prompt used for live spawns")
	return cmd
}

package evalrig

import (
	"context"
	"encoding/json"
	"fmt"
	"os"
	"os/exec"
	"time"
)

// Stage drives the sibling Zellij pane where demonstrations run. The control
// deck types commands into it with `zellij action paste` + `send-keys Enter`,
// targeting the pane by id so the deck never has to surrender focus. Discovery
// matches the pane the layout names "stage" (the same title-match the runtime
// adapter uses for its "agent" pane).
//
// Outside Zellij (Available()==false) every method is a graceful no-op, so the
// deck still runs as a plain matrix viewer for development.
type Stage struct {
	session string
	paneID  string
	run     zellijRunner
}

// zellijRunner executes a `zellij` invocation; injectable so the deck can be
// tested without a live multiplexer.
type zellijRunner func(ctx context.Context, args ...string) ([]byte, error)

// paneInfo mirrors the fields the deck needs from `zellij action list-panes
// --json` (see internal/adapters/runtime/zellij: the same shape and title match).
type paneInfo struct {
	ID       int    `json:"id"`
	IsPlugin bool   `json:"is_plugin"`
	Title    string `json:"title"`
}

const (
	stagePaneTitle = "stage"
	deckPaneTitle  = "deck"
)

// NewStage discovers the stage pane in the current Zellij session, if any.
func NewStage(ctx context.Context) *Stage {
	return newStage(ctx, os.Getenv("ZELLIJ_SESSION_NAME"), execZellij)
}

func newStage(ctx context.Context, session string, run zellijRunner) *Stage {
	s := &Stage{session: session, run: run}
	if s.session != "" {
		s.paneID = s.discoverStagePane(ctx)
	}
	return s
}

