func TestStageDiscoversPaneByTitle(t *testing.T) {
	f := &fakeZellij{listJSON: `[
		{"id":0,"is_plugin":false,"title":"deck"},
		{"id":1,"is_plugin":true,"title":"stage"},
		{"id":2,"is_plugin":false,"title":"stage"}
