176	func cellGlyph(state cellState, status conformance.Status) (string, lipgloss.Color) {
177		switch state {
178		case cellRunning:
179			return "•", colYellow
180		case cellDone:
181			switch status {
182			case conformance.StatusPass:
183				return "✓", colGreen
184			case conformance.StatusFail:
185				return "✗", colRed
186			case conformance.StatusGap:
187				return "▲", colOrange
188			case conformance.StatusSkip:
189				return "–", colDim
190			}
191		}
192		return "·", colDim
193	}
